-- Gerado por scripts/insert_natal_deco.mjs — "Silhueta de Natal para Porta" (rascunho, família Decoração)
insert into prod_designs (id, nome, descricao, familia, estado, acesso_maker, disponivel_consumidor, capa_familia, usa_modo, tags, preco_creditos, scad_template, generation_schema, parametros_default)
values ('silhueta_porta', 'Silhueta de Natal para Porta', 'Cena de Natal em silhueta (trenó, renas, pinheiros, presépio ou casinhas) para pôr em cima do aro de uma porta, de uma janela ou numa prateleira, com aba de apoio atrás.', 'Decoração', 'rascunho', 'gratuito', false, false, false,
  array['silhueta', 'porta', 'trenó', 'renas', 'natal', 'parede'], 1, $tpl$// Silhueta de Natal para Porta — o modelo está em templates/decoracao/partes/silhueta_porta.scad (backend)
include </app/templates/decoracao/silhueta_porta.scad>
$tpl$, '{"engine":"openscad","version":1,"parameters":{"deco":{"order":0,"default":"silhueta_porta","ui":{"widget":"hidden"}},"cena":{"order":1,"default":"Trenó","ui":{"label":"Cena","widget":"select","options":["Renas","Pinheiros","Presépio","Trenó","Casinhas"]}},"largura":{"order":2,"type":"number","min":80,"max":250,"unit":"mm","default":220,"ui":{"label":"Largura","widget":"slider","step":1}},"espessura":{"order":3,"type":"number","min":2,"max":6,"unit":"mm","default":3,"ui":{"label":"Espessura","widget":"slider","step":0.2}},"aba":{"order":4,"type":"number","min":0,"max":40,"unit":"mm","default":15,"ui":{"label":"Aba de apoio (0 = sem aba)","widget":"slider","step":1}},"espelhar":{"order":5,"type":"boolean","default":false,"ui":{"label":"Virada para o outro lado","widget":"checkbox"}},"info_silhueta":{"order":99,"default":null,"ui":{"widget":"info","text":"🚪 Imprime deitada (a aba fica de pé, ao longo do chão da cena). A aba assenta em cima do aro da porta; fixa com fita-cola de dupla face ou massa adesiva. Fica muito bem a preto."}}}}'::jsonb, '{}'::jsonb)
on conflict (id) do update set nome = excluded.nome, descricao = excluded.descricao, tags = excluded.tags,
  scad_template = excluded.scad_template, generation_schema = excluded.generation_schema;
